@namespace sv_dec434a05a8c437f8e8c895b917a680b.Components.Pages.Apply

<nav aria-label="Application steps" class="mb-4">
    <ol class="list-group list-group-horizontal text-center">
        @for (int i = 0; i < StepNames.Length; i++)
        {
            var step = i;
            var isCompleted = step < CurrentStep;
            var isCurrent = step == CurrentStep;
            var isFuture = step > CurrentStep;

            <li class="list-group-item flex-fill @(isCurrent ? "list-group-item-primary fw-bold" : "") @(isFuture ? "text-muted" : "") @(isCompleted ? "list-group-item-success" : "")"
                style="@(isCompleted ? "cursor: pointer;" : "")"
                role="@(isCompleted ? "button" : "")"
                @onclick="() => GoToStep(step)">
                @if (isCompleted)
                {
                    <span>&#10003; </span>
                }
                <span>@StepNames[step]</span>
            </li>
        }
    </ol>
</nav>

@code {
    private static readonly string[] StepNames =
    {
        "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit"
    };

    [Parameter, EditorRequired] public int CurrentStep { get; set; }
    [Parameter, EditorRequired] public EventCallback<int> OnStepClicked { get; set; }

    private async Task GoToStep(int step)
    {
        if (step < CurrentStep)
        {
            await OnStepClicked.InvokeAsync(step);
        }
    }
}

